{% doc %}
  Fulldev UI price styles. Use native markup with its data-slot parts.
{% enddoc %}

{{ 'ui-price.css' | asset_url | stylesheet_tag }}

/* Fulldev UI's price: the current value, the higher compare-at price struck through, a savings
   badge, and the unit price on its own line. */
[data-slot='price'] {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--spacing) calc(var(--spacing) * 2);
  font-size: 0.875rem;
}
[data-slot='price-value'] {
  display: inline-flex;
  color: var(--foreground);
  flex-wrap: wrap;
  align-items: center;
  gap: var(--spacing) calc(var(--spacing) * 2);
  line-height: 1.25;
}
[data-slot='price-value'] del {
  color: var(--muted-foreground);
  font-size: 0.875rem;
}
.price__badge {
  padding: calc(var(--spacing) * 0.5) calc(var(--spacing) * 2);
  border-radius: 9999px;
  background: var(--muted);
  color: var(--foreground);
  font-size: 0.75rem;
  font-weight: 500;
  line-height: 1rem;
}
[data-slot='price'] [data-slot='price-unit'] {
  width: 100%;
}
[data-slot='price-unit'] {
  font-size: 0.75rem;
  color: var(--muted-foreground);
}
.price--lg {
  font-size: 1.25rem;
  font-weight: 500;
}
